# -*- coding: utf-8 -*-
import json, io

W = "https://en.wiktionary.org/wiki/"

entry = {
 "entry": 0,
 "root": "Gwhen 1",
 "verdict": "plausible",
 "modern_form": "PIE *gʷʰen- 'to swell, abound' (Pokorny IEW 491, 1. gʷhen-; Watkins/AHD gʷhen-²)",
 "note": "The root box itself is correct and correctly cited: Pokorny's IEW p.491 heads 'Root/lemma: gʷhen-1, Meaning: to swell, abound', and its material is exactly the 'fill/abundance' family (Skt. ā-ghaná- 'tumescent', ghaná- 'dense', Gk. euthenein 'flourish', Lith. gana 'enough', OCS gonĕti 'suffice') — and, crucially, Pokorny himself lists there 'npers. a-gandan füllen'. Watkins repeats it as 'gʷhen-². To swell, abound … [Pok. 1. gʷhen- 491]'. So the label 'Indo-European', the number '1' and the gloss 'to swell, fill' are all right. What is wrong is the use Nourai makes of the root: the whole page hangs on the Avestan/Old Persian verb kan- 'to dig' (node 1), and neither Pokorny nor any modern handbook derives that verb from *gʷʰen-. Pokorny puts Skt. khan-/Av.-OP kan- 'dig' in his appendix on the tenues aspiratae (IEW p.634), tentatively under ken- 'to scrape' (p.559 ff.); LIV reconstructs an independent *kenh₂- 'to dig' and Cheung (2007) accordingly separates three homophonous Iranian roots — *kan¹ 'to throw, place, destroy', *kan² 'to fill', *kanH¹ 'to dig'. Only the second of these (āgandan) belongs under Pokorny 491. Nourai's own cited Persian authority, Abolghasemi (FFD p.26), says the same in as many words. So: root real and correctly glossed, but the tree built on it merges three distinct roots.",
 "note_fa": "جعبهٔ ریشه درست است: پوکورنی در صفحهٔ ۴۹۱ فرهنگ خود مدخل «gʷhen-1» را با معنای «آماسیدن، آکنده و فراوان بودن» آورده و در همان‌جا خودِ فعلِ فارسیِ «آگندن» را به‌عنوان بازماندهٔ آن نام برده است؛ واتکینز نیز همین ریشه را «gʷhen-²: to swell, abound» با ارجاع به پوکورنی ۴۹۱ ثبت کرده است. پس برچسب «هندواروپایی»، شمارهٔ ۱ و معنای «آماسیدن، آکندن» همگی درست‌اند. ایراد کار در جای دیگری است: نورایی همهٔ درخت را از فعل اوستایی/پارسی‌باستان kan- «کندن، حفر کردن» آویخته است، حال آنکه هیچ پژوهش امروزی این فعل را از *gʷʰen- نمی‌داند؛ خود پوکورنی (ص ۶۳۴) kan-/khan- «کندن» را با تردید به ریشهٔ ken- «خراشیدن» (ص ۵۵۹ به بعد) می‌بندد و LIV آن را ریشهٔ مستقل *kenh₂- می‌گیرد. چونگ (۲۰۰۷) سه ریشهٔ هم‌آوای ایرانی را از هم جدا می‌کند: *kan¹ «افکندن، نهادن، ویران کردن»، *kan² «آکندن، پر کردن» و *kanH¹ «کندن». تنها ریشهٔ دوم (آگندن) زیر مدخل پوکورنی ۴۹۱ جای دارد. ابوالقاسمی نیز — که خودِ نورایی او را در همین صفحه (FFD:26) گواه گرفته — به‌صراحت می‌نویسد در ایرانی باستان دو kan جداگانه بوده است. حکم: ریشه درست، ولی درختِ بر آن استوار سه ریشه را در هم آمیخته است.",
 "sources": [
   "https://en.wiktionary.org/wiki/Reconstruction:Proto-Indo-European/g%CA%B7%CA%B0en-",
   "https://www.etymonline.com/word/cane"
 ],
 "ref_check": [
   {"ref": "POK:491", "status": "supports", "note": "POK_full.txt (indo-european.info dump), block ending 'Page(s): 491': 'Root / lemma: g\"hen-1 / Meaning: to swell, abound / Material: Old Indic a-ghana- \"tumescent, plentiful, luscious\", ghana- \"dense, thick\" …; npers. a-gandan …; gr. euthenein \"flourish\"; Lith. gana \"sufficient\"; OCS gonetъ \"suffice\". References: WP. I 679, WH. I 479'. Page number and gloss both exactly as Nourai cites. (The next block, 'g\"hen-2(a)- to hit', is Pokorny 491-493 — a different root.)"}
 ],
 "consulted": [
   {"src": "AHD", "where": "Watkins 1985, s.v. gʷhen-²", "stance": "supports", "note": "AHD_watkins1985.txt: 'gʷhen-². To swell, abound. Suffixed form *gʷhen-eyo- in Greek euthenein …: EUTHENICS. [Pok. 1. gʷhen- 491.]' — same root, same page, but Watkins lists no Iranian 'dig' word under it."},
   {"src": "POK", "where": "IEW p.634 (appendix on the tenues aspiratae)", "stance": "contradicts", "note": "POK_full.txt: 'To the same root root ken- (above 559 ff.) could belong Old Indic khanati \"digs\" … Avestan Old pers. kan- \"dig\" (k- from kn- from the compounds with us-, ham-).' Pokorny thus assigns Av./OP kan- to ken-, not to gʷhen-."},
   {"src": "CHEUNG", "where": "EDIV pp. 229-233", "stance": "contradicts", "note": "CHEUNG.txt distinguishes '*kan¹ to throw, place, put; to destroy', '*kan² to fill' and '*kanH¹ to dig' (the latter '«PIE ? *kenH₂- \"to dig\" > LIV: 344'), and remarks 'In many Iranian languages the roots *kan¹, *kanH¹ and *kan² … are homonymous and therefore often show mutual interference.'"},
   {"src": "ARY", "where": "Aryanpur pp. 66 and 411", "stance": "partial", "note": "ARY_pages.txt pdf p.66 puts آکندن/آگندن under the PIE root whose cognates it lists as Skt. ghana-, Lith. gana/ganėti, Arm. yogn, Gk. euthenein, OCS gonĕti (= Pokorny's gʷhen-1), while pdf p.411 gives کندن a wholly separate entry (Av. kan-, OP kan-, Arm. akan, Pahl. kandan, Skt. khan-). Aryanpur therefore also keeps the two apart."}
 ],
 "nodes": []
}

N = entry["nodes"].append

N({
